UPDATE t_shopping_item
SET
    name = #{item.name}
  , memo = #{item.memo}
  , store_type = #{item.storeType}
  , status = #{item.status}
  , favorite = #{item.favorite}
  , purchased_at = #{item.purchasedAt}
  , update_user_id = #{userId}
  , update_program = #{program}
WHERE
    shopping_item_id = #{item.shoppingItemId}
